import time
import threading
from dataclasses import dataclass
from typing import Optional, Dict, Any

@dataclass(frozen=True)
class TokenBucketConfig:
    capacity: float = 1024.0 * 1024.0  # 1 MB bucket capacity
    refill_rate: float = 100.0 * 1024.0 # 100 KB/s refill rate

class LeakyBucketTrafficShaper:
    """Thread-safe leaky-bucket / token-bucket traffic shaper enforcing strict per-peer bandwidth caps."""
    def __init__(self, config: Optional[TokenBucketConfig] = None) -> None:
        self.config = config or TokenBucketConfig()
        self.tokens = self.config.capacity
        self.last_refill = time.time()
        self._lock = threading.Lock()
        self.total_shaped_bytes = 0
        self.total_dropped_bytes = 0

    def _refill_unlocked(self, now: float) -> None:
        elapsed = now - self.last_refill
        if elapsed > 0:
            added = elapsed * self.config.refill_rate
            self.tokens = min(self.config.capacity, self.tokens + added)
            self.last_refill = now

    def consume(self, cost_bytes: int, now: Optional[float] = None) -> bool:
        """Attempts to consume tokens for a packet of given size. Returns True if permitted."""
        if cost_bytes <= 0:
            return True
        current_time = now if now is not None else time.time()
        with self._lock:
            self._refill_unlocked(current_time)
            if self.tokens >= cost_bytes:
                self.tokens -= cost_bytes
                self.total_shaped_bytes += cost_bytes
                return True
            else:
                self.total_dropped_bytes += cost_bytes
                return False

    def get_metrics(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "capacity": self.config.capacity,
                "refill_rate": self.config.refill_rate,
                "current_tokens": self.tokens,
                "total_shaped_bytes": self.total_shaped_bytes,
                "total_dropped_bytes": self.total_dropped_bytes,
            }

class PeerTrafficShaperManager:
    """Manages independent leaky bucket traffic shapers per peer."""
    def __init__(self, default_config: Optional[TokenBucketConfig] = None) -> None:
        self.default_config = default_config or TokenBucketConfig()
        self._shapers: Dict[str, LeakyBucketTrafficShaper] = {}
        self._lock = threading.Lock()

    def get_shaper(self, peer_id: str) -> LeakyBucketTrafficShaper:
        with self._lock:
            if peer_id not in self._shapers:
                self._shapers[peer_id] = LeakyBucketTrafficShaper(self.default_config)
            return self._shapers[peer_id]

    def remove_peer(self, peer_id: str) -> None:
        with self._lock:
            self._shapers.pop(peer_id, None)

import asyncio
import json
import logging
import time
import threading
from typing import Any, Callable, Dict, Optional, Tuple, Union
from gossipmesh.p2p.parser import ZeroCopyPacketParser
from gossipmesh.p2p.ratelimit import PeerRateLimiter, RateLimitConfig
from gossipmesh.p2p.crypto import EphemeralSessionKeyRotator, encrypt_payload, decrypt_payload
from gossipmesh.p2p.erasure import ErasureCoder
from gossipmesh.p2p.traffic_shaper import PeerTrafficShaperManager, TokenBucketConfig

class P2PSessionTransport:
    """Manages peer-to-peer transport streams with automatic key rotation
every 1000 messages or 300 seconds without dropping streams."""
    def __init__(self, max_messages: int=1000, max_time_seconds: float=300.0):
        self.max_messages = max_messages
        self.max_time_seconds = max_time_seconds
        self.message_count = 0
        self.created_at = time.time()
        self.rotator = EphemeralSessionKeyRotator()
        self._lock = threading.Lock()

    def initialize_session(self, peer_public_bytes: bytes):
        with self._lock:
            self.rotator.initialize_session(peer_public_bytes)

    def _should_rotation_unlocked(self) -> bool:
        elapsed = time.time() - self.created_at
        return self.message_count >= self.max_messages or elapsed >= self.max_time_seconds

    def should_rotate(self) -> bool:
        with self._lock:
            return self._should_rotation_unlocked()

    def _trigger_rotation_unlocked(self) -> bytes:
        self.message_count = 0
        self.created_at = time.time()
        return self.rotator.rotate()

    def trigger_rotation(self) -> bytes:
        with self._lock:
            return self._trigger_rotation_unlocked()

    def send_message(self, plaintext: bytes) -> bytes:
        with self._lock:
            self.message_count += 1
            if self._should_rotation_unlocked():
                self._trigger_rotation_unlocked()
            return encrypt_payload(self.rotator.current_key, plaintext)

    def receive_message(self, ciphertext: bytes) -> bytes:
        with self._lock:
            self.message_count += 1
            if self._should_rotation_unlocked():
                self._trigger_rotation_unlocked()
            return decrypt_payload(self.rotator.current_key, ciphertext)

class TransportTelemetry:
    """Telemetry tracking metrics for gossip transport layer."""
    def __init__(self) -> None:
        self.sent_count = 0
        self.sent_bytes = 0
        self.received_count = 0
        self.received_bytes = 0
        self.dropped_count = 0
        self._lock = threading.Lock()

    def record_sent(self, size_bytes: int) -> None:
        with self._lock:
            self.sent_count += 1
            self.sent_bytes += size_bytes

    def record_received(self, size_bytes: int) -> None:
        with self._lock:
            self.received_count += 1
            self.received_bytes += size_bytes

    def record_dropped(self) -> None:
        with self._lock:
            self.dropped_count += 1

    def to_dict(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "sent_count": self.sent_count,
                "sent_bytes": self.sent_bytes,
                "received_count": self.received_count,
                "received_bytes": self.received_bytes,
                "dropped_count": self.dropped_count,
            }

class TransportSocketReader:
    """Reads zero-copy packet structures from an asyncio stream reader."""
    def __init__(self, reader: asyncio.StreamReader, expected_magic: int=1196246355) -> None:
        self.reader = reader
        self.expected_magic = expected_magic

    async def read_packet(self) -> Optional[Tuple[int, str, memoryview]]:
        try:
            header = await self.reader.readexactly(12)
            if len(header) < 12:
                return None
            magic = int.from_bytes(header[0:4], "big")
            if magic != self.expected_magic:
                return None
            length = int.from_bytes(header[4:8], "big")
            topic_len = int.from_bytes(header[8:12], "big")
            topic_bytes = await self.reader.readexactly(topic_len)
            topic = topic_bytes.decode("utf-8")
            body = await self.reader.readexactly(length)
            return (magic, topic, memoryview(body))
        except (asyncio.IncompleteReadError, Exception):
            return None

class GossipTransport:
    """Main GossipMesh transport layer integrating erasure coding, rate limiting, and handlers."""
    def __init__(self, node_id: str, k: int=4, m: int=2, config: Optional[RateLimitConfig] = None, token_config: Optional[TokenBucketConfig] = None) -> None:
        self.node_id = node_id
        self.erasure = ErasureCoder(k=k, m=m)
        self.limiter = PeerRateLimiter(config)
        self.shaper_manager = PeerTrafficShaperManager(token_config)
        self.telemetry = TransportTelemetry()
        self.handlers: Dict[str, Callable[[Any], None]] = {}
        self._sessions: Dict[str, P2PSessionTransport] = {}
        self._lock = threading.Lock()

    def register_handler(self, topic: str, handler: Callable[[Any], None]) -> None:
        self.handlers[topic] = handler

    def _get_session(self, peer_id: str) -> P2PSessionTransport:
        with self._lock:
            if peer_id not in self._sessions:
                self._sessions[peer_id] = P2PSessionTransport()
            return self._sessions[peer_id]

    async def send_payload(self, peer_id: str, payload: Union[bytes, str, dict, int], use_erasure: bool=False) -> bool:
        if isinstance(payload, dict):
            data = json.dumps(payload).encode("utf-8")
        elif isinstance(payload, str):
            data = payload.encode("utf-8")
        elif isinstance(payload, int):
            data = str(payload).encode("utf-8")
        elif isinstance(payload, bytes):
            data = payload
        else:
            data = str(payload).encode("utf-8")

        shaper = self.shaper_manager.get_shaper(peer_id)
        if not shaper.consume(len(data)):
            self.telemetry.record_dropped()
            return False

        session = self._get_session(peer_id)
        _ = session.send_message(data)
        self.telemetry.record_sent(len(data))
        return True

    async def receive_payload(self, peer_id: str, payload: Union[bytes, str, dict, int], topic: str='default') -> Optional[Any]:
        if isinstance(payload, bytes):
            size_bytes = len(payload)
        else:
            size_bytes = len(str(payload).encode("utf-8"))

        self.telemetry.record_received(size_bytes)
        handler = self.handlers.get(topic)
        if handler:
            handler(payload)
        return payload

    async def get_telemetry_metrics(self) -> Dict[str, Any]:
        metrics = self.telemetry.to_dict()
        return metrics
